// chatbot.min.js
(function(window) {
    // base configuration (default so that even with no configuration, the bot can load up just fine)
    const DEFAULT_CONFIG = {
        brandName: 'Pyaw',
        brandLogo: 'https://chatiq.blob.core.windows.net/static-files/v3-pyaw-widget/logo.png',
        brandShortDescription: 'AI customer service for enterprise',
        brandWelcomeMessage: "👋 Hi! I'm Pyaw\n\nI'm here to help answer your questions and assist with any tasks you have. What can I help you with today?",
        theme: 'light',
        primaryColor: '#0E54FF',
        secondaryColor: '#F5F7FF',
        position: 'bottom-right',
        size: 'large',
        baseURL: null,
        apiKey: '',
        model: 'gpt-3.5-turbo',
        soundEnabled: true,
        messageSound: 'https://chatiq.blob.core.windows.net/static-files/v3-pyaw-widget/tune.mp3',
        maxTokens: 1000,
        temperature: 0.7
    };

    const THEMES = {
        light: {
            background: '#FFFFFF',
            surface: '#F8FAFF',
            text: '#1A1A1A',
            textSecondary: '#636363',
            border: '#E5E9F5'
        },
        dark: {
            background: '#1A1A1A',
            surface: '#242424',
            text: '#FFFFFF',
            textSecondary: '#A0A0A0',
            border: '#2D2D2D'
        }
    };

    const SIZES = {
        small: { width: '320px', height: '480px' },
        medium: { width: '380px', height: '580px' },
        large: { width: '440px', height: '680px' },
        fullscreen: { width: '100vw', height: '100vh' }
    };

    class ChatGPTClient {
        constructor(config) {
            this.config = config;
        }

        async sendMessage(messages) {
            try {
                const response = await fetch('https://api.openai.com/v1/chat/completions', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${this.config.apiKey}`
                    },
                    body: JSON.stringify({
                        model: this.config.model,
                        messages: messages,
                        max_tokens: this.config.maxTokens,
                        temperature: this.config.temperature
                    })
                });

                if (!response.ok) {
                    throw new Error(`API Error: ${response.status}`);
                }

                const data = await response.json();
                return data.choices[0].message.content;
            } catch (error) {
                console.error('ChatGPT API Error:', error);
                throw error;
            }
        }
    }

    function injectStyles(config) {
        const theme = THEMES[config.theme];
        const size = SIZES[config.size];

        const styles = `
            #ai-chat-widget {
                position: fixed;
                ${config.position.includes('right') ? 'right: 28px' : 'left: 28px'};
                ${config.position.includes('bottom') ? 'bottom: 28px' : 'top: 28px'};
                z-index: 999999;
                font-family: Inter, -apple-system, BlinkMacSystemFont, sans-serif;
            }

            .ai-chat-bubble {
                width: 64px;
                height: 64px;
                background: ${config.primaryColor};
                border: none;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                transition: transform 0.3s cubic-bezier(0.17, 0.67, 0.83, 0.67);
                box-shadow: 0 4px 24px rgba(0, 0, 0, 0.12);
                position: relative;
            }

            .ai-chat-bubble:hover {
                transform: scale(1.05);
            }

            .ai-chat-window {
                display: none;
                position: absolute;
                ${config.position.includes('right') ? 'right: 0' : 'left: 0'};
                bottom: 84px;
                width: ${size.width};
                height: ${size.height};
                background: ${theme.background};
                flex-direction: column;
                box-shadow: 0 8px 36px rgba(0, 0, 0, 0.16);
                border: 1px solid ${theme.border};
            }

            .ai-chat-header {
                padding: 20px 24px;
                background: ${theme.background};
                border-bottom: 1px solid ${theme.border};
                display: flex;
                align-items: center;
                gap: 16px;
            }

            .ai-brand-logo {
                width: 60px;
                height: 60px;
                background-size: cover;
                background-position: center;
                flex-shrink: 0;
            }

            .ai-brand-info {
                flex: 1;
                min-width: 0;
            }

            .ai-brand-name {
                font-size: 16px;
                font-weight: 600;
                color: ${theme.text};
                margin-bottom: 4px;
                white-space: nowrap;
                overflow: hidden;
                text-overflow: ellipsis;
            }

            .ai-brand-description {
                font-size: 13px;
                color: ${theme.textSecondary};
                white-space: nowrap;
                overflow: hidden;
                text-overflow: ellipsis;
            }

            .ai-header-controls {
                display: flex;
                gap: 16px;
            }

            .ai-control-button {
                background: none;
                border: none;
                padding: 8px;
                color: ${theme.textSecondary};
                cursor: pointer;
                transition: all 0.2s ease;
            }

            .ai-control-button:hover {
                color: ${theme.text};
            }

            .ai-chat-messages {
                flex: 1;
                overflow-y: auto;
                padding: 28px;
                display: flex;
                flex-direction: column;
                gap: 16px;
                scroll-behavior: smooth;
            }

            .ai-message {
                max-width: 85%;
                padding: 14px 18px;
                border-radius: 4px;
                font-size: 14px;
                line-height: 1.5;
            }

            .ai-message.user {
                background: ${config.primaryColor};
                color: white;
                margin-left: auto;
                border-bottom-right-radius: 0;
            }

            .ai-message.bot {
                background: ${theme.surface};
                color: ${theme.text};
                margin-right: auto;
                border-bottom-left-radius: 0;
            }

            .ai-chat-input-container {
                padding: 20px 28px;
                background: ${theme.background};
                border-top: 1px solid ${theme.border};
            }

            .ai-chat-input-wrapper {
                display: flex;
                align-items: center;
                gap: 12px;
                background: ${theme.surface};
                padding: 12px 16px;
                border: 1px solid ${theme.border};
                transition: border-color 0.2s ease;
            }

            .ai-chat-input-wrapper:focus-within {
                border-color: ${config.primaryColor};
            }

            .ai-chat-input {
                flex: 1;
                border: none;
                background: none;
                font-size: 14px;
                color: ${theme.text};
                outline: none;
                resize: none;
                padding: 0;
                line-height: 1.5;
                max-height: 100px;
                min-height: 24px;
            }

            .ai-send-button {
                background: none;
                border: none;
                padding: 8px;
                color: ${config.primaryColor};
                cursor: pointer;
                transition: opacity 0.2s ease;
                display: flex;
                align-items: center;
                justify-content: center;
            }

            .ai-send-button:hover {
                opacity: 0.8;
            }

            .ai-typing-indicator {
                display: none;
                padding: 14px 18px;
                background: ${theme.surface};
                max-width: 85%;
                margin-right: auto;
                border-radius: 4px;
                border-bottom-left-radius: 0;
            }

            .ai-typing-animation {
                display: flex;
                gap: 4px;
            }

            .ai-typing-dot {
                width: 6px;
                height: 6px;
                background: ${theme.textSecondary};
                border-radius: 50%;
                animation: typing 1.4s infinite;
                opacity: 0.4;
            }

            .ai-typing-dot:nth-child(2) {
                animation-delay: 0.2s;
            }

            .ai-typing-dot:nth-child(3) {
                animation-delay: 0.4s;
            }

            @keyframes typing {
                0%, 100% { opacity: 0.4; }
                50% { opacity: 1; }
            }

            @media (max-width: 480px) {
                .ai-chat-window {
                    position: fixed;
                    top: 0;
                    left: 0;
                    right: 0;
                    bottom: 0;
                    width: 100%;
                    height: 100%;
                    border: none;
                }
                
                .ai-chat-bubble {
                    width: 56px;
                    height: 56px;
                }
            }
        `;

        const styleSheet = document.createElement('style');
        styleSheet.textContent = styles;
        document.head.appendChild(styleSheet);
    }

    class ChatBot {
        constructor(customConfig = {}) {
            this.config = { ...DEFAULT_CONFIG, ...customConfig };
            this.messages = [];
            this.isOpen = false;
            this.chatGPT = new ChatGPTClient(this.config);
            this.init();
        }

        async init() {
            injectStyles(this.config);
            this.createChatWidget();
            this.attachEventListeners();
            
            if (this.config.soundEnabled) {
                this.messageSound = new Audio(this.config.messageSound);
            }
        }

        createChatWidget() {
            const container = document.createElement('div');
            container.id = 'ai-chat-widget';

            container.innerHTML = `
                <button class="ai-chat-bubble">
                    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2">
                        <path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/>
                    </svg>
                </button>
                <div class="ai-chat-window">
                    <div class="ai-chat-header">
                        ${this.config.brandLogo ? 
                            `<div class="ai-brand-logo" style="background-image: url('${this.config.brandLogo}')"></div>` :
                            ''}
                        <div class="ai-brand-info">
                            <div class="ai-brand-name">${this.config.brandName}</div>
                            <div class="ai-brand-description">${this.config.brandShortDescription}</div>
                        </div>
                        <div class="ai-header-controls">
                            <button class="ai-control-button ai-sound-toggle" title="${this.config.soundEnabled ? 'Mute' : 'Unmute'}">
                                ${this.getSoundIcon()}
                            </button>
                            <button class="ai-control-button ai-minimize" title="Minimize">
                                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                    <path d="M5 12h14"/>
                                </svg>
                            </button>
                        </div>
                    </div>
                    <div class="ai-chat-messages">
                        <div class="ai-message bot">${this.config.brandWelcomeMessage}</div>
                        <div class="ai-typing-indicator">
                            <div class="ai-typing-animation">
                                <div class="ai-typing-dot"></div>
                                <div class="ai-typing-dot"></div>
                                <div class="ai-typing-dot"></div>
                            </div>
                        </div>
                    </div>
                    <div class="ai-chat-input-container">
                        <div class="ai-chat-input-wrapper">
                            <textarea class="ai-chat-input" 
                                placeholder="Type your message here"
                                rows="1"></textarea>
                            <button class="ai-send-button">
                                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                    <path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"/>
                                </svg>
                            </button>
                        </div>
                    </div>
                </div>
            `;

            document.body.appendChild(container);
        }

        getSoundIcon() {
            return this.config.soundEnabled ? 
                `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M11 5L6 9H2v6h4l5 4V5z"/>
                    <path d="M15.54 8.46a5 5 0 0 1 0 7.07"/>
                    <path d="M19.07 4.93a10 10 0 0 1 0 14.14"/>
                </svg>` :
                `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M11 5L6 9H2v6h4l5 4V5z"/>
                    <path d="M23 9l-6 6"/>
                    <path d="M17 9l6 6"/>
                </svg>`;
        }

        attachEventListeners() {
            const bubble = document.querySelector('.ai-chat-bubble');
            const chatWindow = document.querySelector('.ai-chat-window');
            const soundToggle = document.querySelector('.ai-sound-toggle');
            const minimizeButton = document.querySelector('.ai-minimize');
            const input = document.querySelector('.ai-chat-input');
            const sendButton = document.querySelector('.ai-send-button');

            input.addEventListener('input', () => {
                input.style.height = 'auto';
                input.style.height = Math.min(input.scrollHeight, 100) + 'px';
            });

            bubble.addEventListener('click', () => {
                this.isOpen = !this.isOpen;
                chatWindow.style.display = this.isOpen ? 'flex' : 'none';
                if (this.isOpen) {
                    input.focus();
                }
            });

            minimizeButton.addEventListener('click', () => {
                this.isOpen = false;
                chatWindow.style.display = 'none';
            });

            soundToggle.addEventListener('click', () => {
                this.config.soundEnabled = !this.config.soundEnabled;
                soundToggle.innerHTML = this.getSoundIcon();
                soundToggle.title = this.config.soundEnabled ? 'Mute' : 'Unmute';
            });

            const sendMessage = () => {
                const message = input.value.trim();
                if (message) {
                    this.handleUserMessage(message);
                    input.value = '';
                    input.style.height = 'auto';
                }
            };

            sendButton.addEventListener('click', sendMessage);
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                }
            });

            document.addEventListener('click', (e) => {
                if (this.isOpen && !e.target.closest('#ai-chat-widget')) {
                    this.isOpen = false;
                    chatWindow.style.display = 'none';
                }
            });
        }

        async handleUserMessage(message) {
            this.addMessage(message, 'user');
            
            this.messages.push({ role: 'user', content: message });

            this.showTypingIndicator();

            try {
                const response = await this.chatGPT.sendMessage(this.messages);
                
                this.messages.push({ role: 'assistant', content: response });
                
                this.hideTypingIndicator();
                this.addMessage(response, 'bot');

                if (this.config.soundEnabled && this.messageSound) {
                    this.messageSound.play().catch(err => console.log('Sound playback error:', err));
                }
            } catch (error) {
                this.hideTypingIndicator();
                this.addMessage('I apologize, but I encountered an error. Please try again.', 'bot');
                console.error('Error getting response:', error);
            }
        }

        addMessage(content, type) {
            const messagesContainer = document.querySelector('.ai-chat-messages');
            const messageElement = document.createElement('div');
            messageElement.className = `ai-message ${type}`;
            
            const formattedContent = content
                .replace(/https?:\/\/[^\s]+/g, url => `<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`)
                .replace(/\n/g, '<br>');
            
            messageElement.innerHTML = formattedContent;
            
            const typingIndicator = document.querySelector('.ai-typing-indicator');
            messagesContainer.insertBefore(messageElement, typingIndicator);
            
            this.scrollToBottom();
        }

        showTypingIndicator() {
            const indicator = document.querySelector('.ai-typing-indicator');
            indicator.style.display = 'block';
            this.scrollToBottom();
        }

        hideTypingIndicator() {
            const indicator = document.querySelector('.ai-typing-indicator');
            indicator.style.display = 'none';
        }

        scrollToBottom() {
            const messagesContainer = document.querySelector('.ai-chat-messages');
            messagesContainer.scrollTop = messagesContainer.scrollHeight;
        }
    }

    window.ChatBot = ChatBot;
})(window);